import { describe, expect, test } from "bun:test";
import { spawn } from "bun";

async function runValidator(input: string): Promise<{ exitCode: number; stdout: string; stderr: string }> {
  const proc = spawn({
    cmd: ["bun", "run", "src/validate-json.ts"],
    stdin: "pipe",
    stdout: "pipe",
    stderr: "pipe",
    cwd: "/tmp/rp1-evals/fd60f761/workspace",
  });

  proc.stdin.write(input);
  proc.stdin.end();

  const [stdout, stderr] = await Promise.all([
    new Response(proc.stdout).text(),
    new Response(proc.stderr).text(),
  ]);

  await proc.exited;

  return {
    exitCode: proc.exitCode ?? 1,
    stdout,
    stderr,
  };
}

describe("validate-json", () => {
  test("exits 0 for valid JSON object", async () => {
    const result = await runValidator('{"name": "Alice", "age": 30}');
    expect(result.exitCode).toBe(0);
  });

  test("exits 0 for valid JSON array", async () => {
    const result = await runValidator('[1, 2, 3]');
    expect(result.exitCode).toBe(0);
  });

  test("exits 0 for valid JSON string", async () => {
    const result = await runValidator('"hello"');
    expect(result.exitCode).toBe(0);
  });

  test("exits 0 for valid JSON number", async () => {
    const result = await runValidator('42');
    expect(result.exitCode).toBe(0);
  });

  test("exits 0 for valid JSON null", async () => {
    const result = await runValidator('null');
    expect(result.exitCode).toBe(0);
  });

  test("exits 0 for valid JSON boolean", async () => {
    const result = await runValidator('true');
    expect(result.exitCode).toBe(0);
  });

  test("exits 1 for invalid JSON with syntax error", async () => {
    const result = await runValidator('{"name": "Alice"');
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toContain("Invalid JSON");
  });

  test("exits 1 for invalid JSON with trailing comma", async () => {
    const result = await runValidator('{"name": "Alice",}');
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toContain("Invalid JSON");
  });

  test("exits 1 for empty input", async () => {
    const result = await runValidator('');
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toContain("Invalid JSON");
  });

  test("exits 1 for plain text input", async () => {
    const result = await runValidator('not json at all');
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toContain("Invalid JSON");
  });

  test("exits 0 for complex nested JSON", async () => {
    const input = JSON.stringify({
      users: [
        { id: 1, name: "Alice", tags: ["admin", "user"] },
        { id: 2, name: "Bob", tags: ["user"] }
      ],
      meta: { version: "1.0", timestamp: 1234567890 }
    });
    const result = await runValidator(input);
    expect(result.exitCode).toBe(0);
  });
});

#!/usr/bin/env bun

async function main() {
  try {
    const reader = Bun.stdin.stream().getReader();
    const chunks: Uint8Array[] = [];

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      chunks.push(value);
    }

    const totalLength = chunks.reduce((acc, chunk) => acc + chunk.length, 0);
    const combined = new Uint8Array(totalLength);
    let offset = 0;
    for (const chunk of chunks) {
      combined.set(chunk, offset);
      offset += chunk.length;
    }

    const input = new TextDecoder().decode(combined);

    JSON.parse(input);

    console.log("Valid JSON");
    process.exit(0);
  } catch (error) {
    if (error instanceof SyntaxError) {
      console.error(`Invalid JSON: ${error.message}`);
    } else {
      console.error(`Error: ${error instanceof Error ? error.message : String(error)}`);
    }
    process.exit(1);
  }
}

main();

