export interface JsonValidationResult {
  valid: boolean;
  data?: unknown;
  error?: string;
}

export function validateJsonSyntax(input: string): JsonValidationResult {
  try {
    const data = JSON.parse(input);
    return { valid: true, data };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    return { valid: false, error: errorMessage };
  }
}

export function isValidJson(input: string): boolean {
  try {
    JSON.parse(input);
    return true;
  } catch {
    return false;
  }
}

export function isJsonObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function isJsonArray(value: unknown): value is unknown[] {
  return Array.isArray(value);
}

export function isJsonPrimitive(value: unknown): value is string | number | boolean | null {
  return (
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean" ||
    value === null
  );
}

export function isJsonString(value: unknown): value is string {
  return typeof value === "string";
}

export function isJsonNumber(value: unknown): value is number {
  return typeof value === "number" && !isNaN(value);
}

export function isJsonBoolean(value: unknown): value is boolean {
  return typeof value === "boolean";
}

export function isJsonNull(value: unknown): value is null {
  return value === null;
}

